25	use mod_quiz\quiz_settings;
26	
27	require_once(__DIR__ . '/../../config.php');
28	require_once($CFG->dirroot.'/mod/quiz/lib.php');
29	require_once($CFG->dirroot.'/mod/quiz/locallib.php');
30	
31	$cmid = required_param('cmid', PARAM_INT);
32	$mode = optional_param('mode', '', PARAM_ALPHA); // One of 'user' or 'group', default is 'group'.
33	
34	$quizobj = quiz_settings::create_for_cmid($cmid);
35	$quiz = $quizobj->get_quiz();
36	$cm = $quizobj->get_cm();
37	$course = $quizobj->get_course();
38	$context = $quizobj->get_context();
39	
40	require_login($course, false, $cm);
41	
42	// Check the user has the required capabilities to list overrides.
43	$canedit = has_capability('mod/quiz:manageoverrides', $context);
44	if (!$canedit) {
45	    require_capability('mod/quiz:viewoverrides', $context);
46	}
47	
48	$quizgroupmode = groups_get_activity_groupmode($cm);
49	$showallgroups = ($quizgroupmode == NOGROUPS) || has_capability('moodle/site:accessallgroups', $context);
50	
51	// Get the course groups that the current user can access.
52	$groups = $showallgroups ? groups_get_all_groups($cm->course) : groups_get_activity_allowed_groups($cm);
53	
54	// Default mode is "group", unless there are no groups.
55	if ($mode != "user" and $mode != "group") {
56	    if (!empty($groups)) {
57	        $mode = "group";
58	    } else {
59	        $mode = "user";
60	    }
61	}
62	$groupmode = ($mode == "group");
63	
64	$url = new moodle_url('/mod/quiz/overrides.php', ['cmid' => $cm->id, 'mode' => $mode]);
65	
66	$title = get_string('overridesforquiz', 'quiz',
67	        format_string($quiz->name, true, ['context' => $context]));
68	$PAGE->set_url($url);
69	$PAGE->set_pagelayout('admin');
70	$PAGE->add_body_class('limitedwidth');
71	$PAGE->set_title($title);
72	$PAGE->set_heading($course->fullname);
73	$PAGE->activityheader->disable();
74	
75	// Activate the secondary nav tab.
76	$PAGE->set_secondary_active_tab("mod_quiz_useroverrides");
77	$PAGE->set_show_navigation_footer(false);
78	
79	// Delete orphaned group overrides.
80	$sql = 'SELECT o.id
81	          FROM {quiz_overrides} o
82	     LEFT JOIN {groups} g ON o.groupid = g.id
83	         WHERE o.groupid IS NOT NULL
84	               AND g.id IS NULL
85	               AND o.quiz = ?';
86	$params = [$quiz->id];
87	$orphaned = $DB->get_records_sql($sql, $params);
88	if (!empty($orphaned)) {
89	    $DB->delete_records_list('quiz_overrides', 'id', array_keys($orphaned));
90	}
91	
92	$overrides = [];
93	$colclasses = [];
94	$headers = [];
95	
96	// Fetch all overrides.
97	if ($groupmode) {
98	    $headers[] = get_string('group');
99	    // To filter the result by the list of groups that the current user has access to.
100	    if ($groups) {
101	        $params = ['quizid' => $quiz->id];
102	        list($insql, $inparams) = $DB->get_in_or_equal(array_keys($groups), SQL_PARAMS_NAMED);
103	        $params += $inparams;
104	
105	        $sql = "SELECT o.*, g.name
106	                  FROM {quiz_overrides} o
107	                  JOIN {groups} g ON o.groupid = g.id
108	                 WHERE o.quiz = :quizid AND g.id $insql
109	              ORDER BY g.name";
110	
111	        $overrides = $DB->get_records_sql($sql, $params);
112	    }
113	
114	} else {
115	    // User overrides.
116	    $colclasses[] = 'colname';
117	    $headers[] = get_string('user');
118	    $userfieldsapi = \core_user\fields::for_identity($context)->with_name()->with_userpic();
119	    $extrauserfields = $userfieldsapi->get_required_fields([\core_user\fields::PURPOSE_IDENTITY]);
120	    $userfieldssql = $userfieldsapi->get_sql('u', true, '', 'userid', false);
121	    foreach ($extrauserfields as $field) {
122	        $colclasses[] = 'col' . $field;
123	        $headers[] = \core_user\fields::get_display_name($field);
124	    }
125	
126	    list($sort, $params) = users_order_by_sql('u', null, $context, $extrauserfields);
127	    $params['quizid'] = $quiz->id;
128	
129	    if ($showallgroups) {
130	        $groupsjoin = '';
131	        $groupswhere = '';
132	
133	    } else if ($groups) {
134	        list($insql, $inparams) = $DB->get_in_or_equal(array_keys($groups), SQL_PARAMS_NAMED);
135	        $groupsjoin = 'JOIN {groups_members} gm ON u.id = gm.userid';
136	        $groupswhere = ' AND gm.groupid ' . $insql;
