45	$quiz = $quizobj->get_quiz();
46	$cm = $quizobj->get_cm();
47	$course = $quizobj->get_course();
48	$context = $quizobj->get_context();
49	$manager = $quizobj->get_override_manager();
50	
51	$url = new moodle_url('/mod/quiz/overrideedit.php');
52	if ($action) {
53	    $url->param('action', $action);
54	}
55	if ($overrideid) {
56	    $url->param('id', $overrideid);
57	} else {
58	    $url->param('cmid', $cmid);
59	}
60	
61	$PAGE->set_url($url);
62	
63	// Activate the secondary nav tab.
64	$PAGE->set_secondary_active_tab("mod_quiz_useroverrides");
65	$PAGE->set_show_navigation_footer(false);
66	
67	require_login($course, false, $cm);
68	
69	// Add or edit an override.
70	$manager->require_manage_capability();
71	
72	if ($overrideid) {
73	    // Editing an override.
74	    $data = clone $override;
75	
76	    if (!$manager->can_view_override($override, $course, $cm)) {
77	        throw new \moodle_exception('invalidoverrideid', 'quiz');
78	    }
79	} else {
80	    // Creating a new override.
81	    $data = new stdClass();
82	}
83	
84	// Merge quiz defaults with data.
85	$keys = ['timeopen', 'timeclose', 'timelimit', 'attempts', 'password', 'duedate'];
86	foreach ($keys as $key) {
87	    if (!isset($data->{$key}) || $reset) {
88	        $data->{$key} = $quiz->{$key};
89	    }
90	}
91	
92	// Prepare reason editor data.
93	if (isset($override->reason)) {
94	    $data->reason_editor = [
95	        'text' => $override->reason,
96	        'format' => $override->reasonformat ?? FORMAT_MOODLE,
97	    ];
