135	            // User override.
136	            $userfieldsapi = \core_user\fields::for_identity($this->context)->with_userpic()->with_name();
137	            $extrauserfields = $userfieldsapi->get_required_fields([\core_user\fields::PURPOSE_IDENTITY]);
138	            if ($this->userid) {
139	                // There is already a userid, so freeze the selector.
140	                $user = $DB->get_record('user', ['id' => $this->userid]);
141	                profile_load_custom_fields($user);
142	                $userchoices = [];
143	                $userchoices[$this->userid] = self::display_user_name($user, $extrauserfields);
144	                $mform->addElement('select', 'userid',
145	                        get_string('overrideuser', 'quiz'), $userchoices);
146	                $mform->freeze('userid');
