1	<?php
2	// Deja el estado de prueba EXACTAMENTE como lo dejó el sembrado, antes de cada corrida (determinismo funcional y visual):
3	//  - borra todos los intentos de los exámenes del curso QA101
4	//  - borra actividades creadas por pruebas (todo lo que no sea el examen sembrado QUIZ-REG ni el banco del curso)
5	//  - borra categorías de preguntas creadas por pruebas (y sus preguntas), conserva las 3 sembradas y la raíz
6	//  - borra notificaciones/mensajes (el contador de la barra superior cambiaría la captura)
7	//  - desactiva tours de usuario y ejecuta las tareas ad hoc pendientes (p. ej. migraciones de mod_qbank que bloquean el banco)
8	// Uso: php /opt/seed/reset.php
9	define('CLI_SCRIPT', true);
10	require('/var/www/moodle/config.php');
11	require_once($CFG->dirroot . '/mod/quiz/locallib.php');
12	require_once($CFG->dirroot . '/course/lib.php');
13	require_once($CFG->libdir . '/questionlib.php');
14	
15	global $DB;
16	\core\session\manager::set_user(get_admin());
17	$course = $DB->get_record('course', ['shortname' => 'QA101'], '*', MUST_EXIST);
18	
19	$intentos = 0;
20	foreach ($DB->get_records('quiz', ['course' => $course->id]) as $quiz) {
21	    $intentos += $DB->count_records('quiz_attempts', ['quiz' => $quiz->id]);
22	    quiz_delete_all_attempts($quiz);
23	}
24	
25	$actividades = 0;
26	$modinfo = get_fast_modinfo($course);
27	foreach ($modinfo->get_cms() as $cm) {
28	    if ($cm->idnumber === 'QUIZ-REG' || $cm->modname === 'qbank') continue;
29	    course_delete_module($cm->id);
30	    $actividades++;
31	}
32	
33	$categorias = 0;
34	$sembradas = ['TEMA-ALG', 'TEMA-GEO', 'TEMA-HIS'];
35	$cmbanco = $DB->get_records_sql("SELECT cm.id FROM {course_modules} cm JOIN {modules} m ON m.id = cm.module
36	                                  WHERE m.name = 'qbank' AND cm.course = ?", [$course->id]);
37	foreach ($cmbanco as $cmb) {
38	    $ctx = context_module::instance($cmb->id);
39	    $cats = $DB->get_records('question_categories', ['contextid' => $ctx->id], 'id DESC');
40	    foreach ($cats as $cat) {
41	        if ($cat->parent == 0 || in_array($cat->idnumber, $sembradas, true)) continue;
42	        // Categorías creadas por pruebas (o la "Default" que Moodle crea al primer uso) se vacían y se borran.
43	        $qids = $DB->get_fieldset_sql("SELECT q.id FROM {question} q JOIN {question_versions} qv ON qv.questionid = q.id
44	                                         JOIN {question_bank_entries} qbe ON qbe.id = qv.questionbankentryid
45	                                        WHERE qbe.questioncategoryid = ?", [$cat->id]);
46	        foreach ($qids as $qid) question_delete_question($qid);
47	        if (!$DB->record_exists('question_bank_entries', ['questioncategoryid' => $cat->id])
48	                && !$DB->record_exists('question_categories', ['parent' => $cat->id])) {
49	            $DB->delete_records('question_categories', ['id' => $cat->id]);
50	            $categorias++;
51	        }
52	    }
53	}
54	
55	$DB->delete_records('notifications');
56	$DB->delete_records('message_popup_notifications');
57	$DB->set_field('tool_usertours_tours', 'enabled', 0);
58	purge_all_caches();
59	echo "reset OK: {$intentos} intentos, {$actividades} actividades y {$categorias} categorías de prueba borradas; notificaciones limpias\n";
60

